{
  "name": "china-mcp-servers",
  "version": "0.1.0",
  "description": "MCP servers for Chinese services that did not have one: Server酱 WeChat push, 中国法定节假日/调休, 百度翻译.",
  "keywords": [
    "mcp",
    "model-context-protocol",
    "china",
    "serverchan",
    "holiday",
    "baidu-translate",
    "ai-agents"
  ],
  "license": "MIT",
  "type": "module",
  "bin": {
    "china-mcp": "dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "vitest run",
    "prepublishOnly": "npm run build",
    "prepare": "npm run build"
  },
  "dependencies": {
    "@modelcontextprotocol/server": "^2.0.0",
    "zod": "^4.2.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zackchewa/china-mcp-servers.git"
  },
  "homepage": "https://github.com/zackchewa/china-mcp-servers#readme"
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { createHash } from 'node:crypto'
import { endpointFor, send } from '../src/servers/serverchan.js'
import { clearCache, dayInfo, isValidDate, yearInfo } from '../src/servers/holiday.js'
import { mapError, safeLang, signOf, translate } from '../src/servers/baidu-translate.js'

function mockFetch(handler: (url: string, init: RequestInit | undefined) => Response | Promise<Response>) {
  const spy = vi.fn(async (url: unknown, init?: unknown) => handler(String(url), init as RequestInit | undefined))
  vi.stubGlobal('fetch', spy)
  return spy
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } })
}

afterEach(() => {
  vi.unstubAllGlobals()
  vi.restoreAllMocks()
  clearCache()
})

describe('Server酱 endpoint selection', () => {
  it('routes a Turbo key (SCT…) to sctapi.ftqq.com', () => {
    expect(endpointFor('SCT123abc')).toBe('https://sctapi.ftqq.com/SCT123abc.send')
  })

  it('routes a Server³ key (sctp<uid>t…) to that uid host', () => {
    // The uid is the digit run after sctp — this is the whole reason the two
    // formats cannot share a host.
    expect(endpointFor('sctp4567txyz')).toBe('https://4567.push.ft07.com/send/sctp4567txyz.send')
  })

  it('rejects a key that is neither format instead of guessing a host', () => {
    expect(() => endpointFor('nope123')).toThrow(/unrecognised SendKey/i)
  })
})

describe('Server酱 send', () => {
  it('posts a form-encoded body and returns data on code 0', async () => {
    const spy = mockFetch(() => json({ code: 0, data: { pushid: '42' } }))
    const result = await send('SCTkey', { title: 'done', desp: '# body' })
    expect(result).toEqual({ pushid: '42' })
    const [, init] = spy.mock.calls[0] as [string, RequestInit]
    expect(init.method).toBe('POST')
    expect(String(init.headers && (init.headers as Record<string, string>)['Content-Type'])).toContain(
      'application/x-www-form-urlencoded',
    )
    const body = new URLSearchParams(String(init.body))
    expect(body.get('title')).toBe('done')
    expect(body.get('desp')).toBe('# body')
  })

  it('treats a non-zero code as failure even though HTTP was 200', async () => {
    mockFetch(() => json({ code: 40001, message: 'bad key' }))
    await expect(send('SCTkey', { title: 'x' })).rejects.toThrow(/invalid or expired/i)
  })

  it('accepts a 2xx with no code field at all', async () => {
    mockFetch(() => json({ data: { ok: 1 } }))
    await expect(send('SCTkey', { title: 'x' })).resolves.toEqual({ ok: 1 })
  })

  it('never leaks the SendKey into an error message', async () => {
    const key = 'SCTsupersecret'
    mockFetch(() => new Response(`upstream said ${key} is bad`, { status: 500 }))
    await expect(send(key, { title: 'x' })).rejects.toThrow(/\*\*\*/)
    await send(key, { title: 'x' }).catch((e: Error) => {
      expect(e.message).not.toContain(key)
    })
  })

  it('requires a title', async () => {
    mockFetch(() => json({ code: 0 }))
    await expect(send('SCTkey', { title: '  ' })).rejects.toThrow(/title is required/i)
  })
})

describe('节假日 holiday', () => {
  const YEAR_2026 = {
    year: 2026,
    days: [
      { name: '国庆节', date: '2026-10-01', isOffDay: true },
      { name: '国庆节', date: '2026-09-27', isOffDay: false },
    ],
  }

  it('classifies a statutory holiday', async () => {
    mockFetch(() => json(YEAR_2026))
    await expect(dayInfo('2026-10-01')).resolves.toMatchObject({ type: 'holiday', isOffDay: true, name: '国庆节' })
  })

  it('classifies a 调休 makeup workday as a working day', async () => {
    mockFetch(() => json(YEAR_2026))
    // A Sunday you must work — the case a naive weekend check gets wrong.
    await expect(dayInfo('2026-09-27')).resolves.toMatchObject({ type: 'makeup-workday', isOffDay: false })
  })

  it('treats an unlisted weekend as off and an unlisted weekday as work', async () => {
    mockFetch(() => json(YEAR_2026))
    await expect(dayInfo('2026-10-03')).resolves.toMatchObject({ type: 'weekend', isOffDay: true })
    await expect(dayInfo('2026-10-07')).resolves.toMatchObject({ type: 'workday', isOffDay: false })
  })

  it('falls back to the second CDN when the first one fails', async () => {
    const spy = mockFetch((url) =>
      url.includes('jsdelivr') ? new Response('nope', { status: 503 }) : json(YEAR_2026),
    )
    await expect(dayInfo('2026-10-01')).resolves.toMatchObject({ type: 'holiday' })
    expect(spy.mock.calls.length).toBe(2)
  })

  it('refuses a wrong-year or empty payload rather than caching an empty calendar', async () => {
    // This is the dangerous failure: a JSON error page would otherwise be cached
    // for 12h and report every holiday as a normal workday.
    mockFetch(() => json({ year: 1999, days: [] }))
    await expect(dayInfo('2026-10-01')).rejects.toThrow(/could not load/i)
  })

  it('validates the date format', async () => {
    mockFetch(() => json(YEAR_2026))
    await expect(dayInfo('2026-13-40')).rejects.toThrow(/YYYY-MM-DD/)
    expect(isValidDate('2026-02-30')).toBe(false)
    expect(isValidDate('2026-02-28')).toBe(true)
  })

  it('splits a year into holidays and makeup workdays', async () => {
    mockFetch(() => json(YEAR_2026))
    const info = await yearInfo(2026)
    expect(info.holidays).toEqual([{ name: '国庆节', date: '2026-10-01' }])
    expect(info.makeupWorkdays).toEqual([{ name: '国庆节', date: '2026-09-27' }])
  })

  it('caches a year rather than refetching it', async () => {
    const spy = mockFetch(() => json(YEAR_2026))
    await dayInfo('2026-10-01')
    await dayInfo('2026-10-02')
    expect(spy.mock.calls.length).toBe(1)
  })
})

describe('百度翻译 Baidu Translate', () => {
  it('signs the RAW text, not the URL-encoded form', async () => {
    // Encoding q before hashing is the number-one cause of 54001.
    const spy = mockFetch(() => json({ from: 'en', to: 'zh', trans_result: [{ src: 'a b', dst: '甲 乙' }] }))
    await translate({ appid: 'APPID', secret: 'SECRET' }, 'a b', 'en', 'zh')
    const [, init] = spy.mock.calls[0] as [string, RequestInit]
    const body = new URLSearchParams(String(init.body))
    const salt = String(body.get('salt'))
    const expected = createHash('md5').update('APPID' + 'a b' + salt + 'SECRET').digest('hex')
    expect(body.get('sign')).toBe(expected)
    expect(signOf('APPID', 'a b', salt, 'SECRET')).toBe(expected)
  })

  it('defaults from=auto and to=zh', async () => {
    const spy = mockFetch(() => json({ trans_result: [{ src: 'hi', dst: '你好' }] }))
    await translate({ appid: 'A', secret: 'S' }, 'hi')
    const body = new URLSearchParams(String((spy.mock.calls[0] as [string, RequestInit])[1].body))
    expect(body.get('from')).toBe('auto')
    expect(body.get('to')).toBe('zh')
  })

  it('bounds input on UTF-8 bytes, not characters', async () => {
    mockFetch(() => json({ trans_result: [] }))
    // 2000 CJK characters is 6000 bytes — over the 标准版 per-call cap.
    await expect(translate({ appid: 'A', secret: 'S' }, '中'.repeat(2000))).rejects.toThrow(/too long/i)
  })

  it('maps Baidu string error codes to actionable messages', async () => {
    mockFetch(() => json({ error_code: '54001', error_msg: 'Invalid Sign' }))
    await expect(translate({ appid: 'A', secret: 'S' }, 'hi')).rejects.toThrow(/signature check failed/i)
    expect(mapError('58000', '').message).toMatch(/IP not allowed/i)
    expect(mapError('99999', 'weird').message).toMatch(/code 99999/)
  })

  it('rejects a malformed language code before calling Baidu', () => {
    expect(() => safeLang('en-US!', 'auto')).toThrow(/bad language code/i)
    expect(safeLang('', 'auto')).toBe('auto')
    expect(safeLang('KOR', 'auto')).toBe('kor')
  })
})

