/**
 * 百度翻译 (Baidu Translate, 标准版) — multi-language text translation.
 *
 * Credentials: BAIDU_TRANSLATE_APPID + BAIDU_TRANSLATE_SECRET. The 标准版 tier is
 * genuinely free (50k chars/month) and has a "暂不认证" path, so you can get a
 * working appid/secret at https://fanyi-api.baidu.com without ID verification.
 *
 * Auth: appid + salt + sign, sign = MD5(appid + q + salt + secret).
 * The one that costs everybody an afternoon: q is concatenated RAW (UTF-8) when
 * building the signed string, and URL-encoded only at the HTTP layer. Encoding q
 * before hashing is the number one cause of error 54001 "invalid sign".
 *
 * Docs: https://fanyi-api.baidu.com/product/113
 */

import { createHash, randomInt } from 'node:crypto'
import { McpServer } from '@modelcontextprotocol/server'
import * as z from 'zod/v4'
import { request, requireEnv } from '../lib/http.js'

const ENDPOINT = 'https://fanyi-api.baidu.com/api/trans/vip/translate'
// 标准版 caps one request at 6000 BYTES (UTF-8), not characters. A CJK character is
// 3 bytes, so bound on byte length or long Chinese input trips Baidu's own error.
const MAX_Q_BYTES = 5800

export type Credentials = { appid: string; secret: string }

/**
 * Baidu uses some non-ISO codes (auto, jp, kor, fra, spa, cht), so allow 2-5
 * letters rather than a strict ISO list, but reject anything else so a typo fails
 * here with a clear message instead of at Baidu with a numeric code.
 */
export function safeLang(raw: string | undefined, fallback: string): string {
  const value = String(raw || '').trim().toLowerCase()
  if (!value) return fallback
  if (!/^[a-z]{2,5}$/.test(value)) {
    throw new Error('百度翻译 Baidu Translate: bad language code (use auto/zh/en/jp/kor/fra…)')
  }
  return value
}

export function signOf(appid: string, text: string, salt: string, secret: string): string {
  return createHash('md5').update(appid + text + salt + secret).digest('hex')
}

export function mapError(code: string, message: string): Error {
  switch (code) {
    case '52001':
    case '52002':
      return new Error('百度翻译 Baidu Translate: service temporarily unavailable, please retry')
    case '52003':
      return new Error('百度翻译 Baidu Translate: APP ID invalid, or translation not enabled for it')
    case '54000':
      return new Error('百度翻译 Baidu Translate: a required parameter is missing')
    case '54001':
      return new Error('百度翻译 Baidu Translate: signature check failed — verify APP ID and secret')
    case '54003':
      return new Error('百度翻译 Baidu Translate: rate limited, please retry (or upgrade in the console)')
    case '54004':
      return new Error('百度翻译 Baidu Translate: account balance exhausted')
    case '54005':
      return new Error('百度翻译 Baidu Translate: long-text requests too frequent, please retry')
    case '58000':
      return new Error('百度翻译 Baidu Translate: caller IP not allowed — disable the IP allowlist or add this host')
    case '58001':
      return new Error('百度翻译 Baidu Translate: unsupported target language')
    case '58002':
      return new Error('百度翻译 Baidu Translate: the service is switched off in the console')
    case '90107':
      return new Error('百度翻译 Baidu Translate: account not verified — finish 实名认证 in the console')
    default:
      return new Error(`百度翻译 Baidu Translate: ${message || 'request failed'} (code ${code})`)
  }
}

export async function translate(
  creds: Credentials,
  q: string,
  from?: string,
  to?: string,
): Promise<{ from: string; to: string; src: string; dst: string; translations: Array<{ src: string; dst: string }> }> {
  const text = String(q || '')
  if (!text.trim()) throw new Error('百度翻译 Baidu Translate: q (text to translate) is required')
  if (Buffer.byteLength(text, 'utf8') > MAX_Q_BYTES) {
    throw new Error(
      '百度翻译 Baidu Translate: text too long (about 6000 bytes / 2000 Chinese characters per call) — split it',
    )
  }
  const fromLang = safeLang(from, 'auto')
  const toLang = safeLang(to, 'zh')
  const salt = String(randomInt(0, 2_147_483_647))
  const sign = signOf(creds.appid, text, salt, creds.secret)

  const form = new URLSearchParams({ q: text, from: fromLang, to: toLang, appid: creds.appid, salt, sign })
  const res = await request(ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': 'china-mcp-servers/0.1 (baidu-translate)',
    },
    body: form.toString(),
    label: '百度翻译 Baidu Translate',
  })

  let body: Record<string, unknown>
  try {
    body = (await res.json()) as Record<string, unknown>
  } catch {
    throw new Error('百度翻译 Baidu Translate: unexpected response, please retry')
  }
  // error_code comes back as a STRING even though it looks numeric.
  if (body.error_code !== undefined && body.error_code !== null) {
    throw mapError(String(body.error_code), String(body.error_msg || ''))
  }

  const results = (Array.isArray(body.trans_result) ? body.trans_result : []) as Array<Record<string, unknown>>
  const translations = results.map((r) => ({ src: String(r.src || ''), dst: String(r.dst || '') }))
  return {
    from: String(body.from || fromLang),
    to: String(body.to || toLang),
    src: translations.map((t) => t.src).join('\n'),
    dst: translations.map((t) => t.dst).join('\n'),
    translations,
  }
}

export function createServer(): McpServer {
  const server = new McpServer({ name: 'baidu-translate', version: '0.1.0' })

  server.registerTool(
    'baidu_translate',
    {
      description:
        'Translate text with Baidu Translate. Source language defaults to auto-detect and target defaults to Chinese. Language codes include auto, zh, en, jp, kor, fra, spa, cht.',
      inputSchema: z.object({
        q: z.string().min(1).describe('Text to translate'),
        from: z.string().optional().describe('Source language code, default auto'),
        to: z.string().optional().describe('Target language code, default zh'),
      }),
    },
    async ({ q, from, to }) => {
      try {
        const creds: Credentials = {
          appid: requireEnv('BAIDU_TRANSLATE_APPID', 'Create one free at https://fanyi-api.baidu.com (标准版).'),
          secret: requireEnv('BAIDU_TRANSLATE_SECRET', 'The 密钥 on the same developer-info page.'),
        }
        const result = await translate(creds, q, from, to)
        return { content: [{ type: 'text', text: JSON.stringify(result) }] }
      } catch (e) {
        return {
          content: [{ type: 'text', text: e instanceof Error ? e.message : 'translation failed' }],
          isError: true,
        }
      }
    },
  )

  return server
}

/** Shared HTTP helper: fixed timeout, no redirect following, honest errors. */

export type FetchOptions = {
  method?: string
  headers?: Record<string, string>
  body?: string
  timeoutMs?: number
  /** Label used in error messages, e.g. "Server酱". */
  label: string
}

export const DEFAULT_TIMEOUT_MS = 15000

/**
 * Redirects are refused rather than followed: every endpoint here is a fixed
 * vendor host, so a redirect means something is wrong (or someone is trying to
 * move the request elsewhere), and credentials can ride in the URL path.
 */
export async function request(url: string, opts: FetchOptions): Promise<Response> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? DEFAULT_TIMEOUT_MS)
  try {
    return await fetch(url, {
      method: opts.method ?? 'GET',
      headers: opts.headers,
      body: opts.body,
      signal: controller.signal,
      redirect: 'error',
    })
  } catch (e) {
    const aborted = e instanceof Error && e.name === 'AbortError'
    throw new Error(`${opts.label}: ${aborted ? 'request timed out' : 'network request failed'}, please retry`)
  } finally {
    clearTimeout(timer)
  }
}

/** Redact a secret from any surfaced string, raw and URL-encoded. */
export function redact(message: string, secret: string): string {
  if (!secret) return message
  let out = message.split(secret).join('***')
  const encoded = encodeURIComponent(secret)
  if (encoded !== secret) out = out.split(encoded).join('***')
  return out
}

/** Read a required credential from the environment, with a useful failure. */
export function requireEnv(name: string, hint: string): string {
  const value = String(process.env[name] ?? '').trim()
  if (!value) throw new Error(`Missing ${name}. ${hint}`)
  return value
}

/**
 * Server酱 (ServerChan / 方糖) — push a notification to your OWN WeChat.
 *
 * Two live key formats exist and they use different hosts. This trips people up,
 * because the docs show only the Turbo one:
 *   Turbo   — key starts with "SCT":   POST https://sctapi.ftqq.com/<KEY>.send
 *   Server³ — key like "sctp<uid>t…":  POST https://<uid>.push.ft07.com/send/<KEY>.send
 * The uid is the digit run in the key, per the official ^sctp(\d+)t regex.
 *
 * Credential: SERVERCHAN_SENDKEY. Free and self-serve — scan-login with WeChat
 * at https://sct.ftqq.com and copy the SendKey.
 *
 * The SendKey travels in the URL path, so it is redacted from every error string.
 */

import { McpServer } from '@modelcontextprotocol/server'
import * as z from 'zod/v4'
import { redact, request, requireEnv } from '../lib/http.js'

const MAX_TITLE = 256
const MAX_DESP = 32 * 1024 // Server酱 caps the markdown body around 32KB.

export function endpointFor(sendkey: string): string {
  const key = sendkey.trim()
  const server3 = /^sctp(\d+)t/i.exec(key)
  if (server3) {
    return `https://${server3[1]}.push.ft07.com/send/${encodeURIComponent(key)}.send`
  }
  if (/^sct/i.test(key)) {
    return `https://sctapi.ftqq.com/${encodeURIComponent(key)}.send`
  }
  throw new Error(
    'Server酱: unrecognised SendKey format. Copy a key starting with SCT (Turbo) or sctp (Server³) from https://sct.ftqq.com',
  )
}

export type SendInput = {
  title: string
  desp?: string
  short?: string
  tags?: string
  channel?: string
}

export async function send(sendkey: string, input: SendInput): Promise<unknown> {
  const key = String(sendkey || '').trim()
  if (!key) throw new Error('Server酱: missing SendKey')
  const title = String(input.title || '').trim()
  if (!title) throw new Error('Server酱: title is required')

  const form = new URLSearchParams()
  form.set('title', title.slice(0, MAX_TITLE))
  if (input.desp) form.set('desp', String(input.desp).slice(0, MAX_DESP))
  if (input.short) form.set('short', String(input.short).slice(0, MAX_TITLE))
  if (input.tags) form.set('tags', String(input.tags).slice(0, MAX_TITLE))
  if (input.channel) form.set('channel', String(input.channel).slice(0, MAX_TITLE))

  const res = await request(endpointFor(key), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
      Accept: 'application/json',
      'User-Agent': 'china-mcp-servers/0.1 (serverchan)',
    },
    body: form.toString(),
    label: 'Server酱',
  })

  const raw = await res.text()
  let body: Record<string, unknown> | null = null
  try {
    body = JSON.parse(raw) as Record<string, unknown>
  } catch {
    body = null
  }

  if (!res.ok) {
    if (res.status === 401 || res.status === 403 || res.status === 404) {
      throw new Error('Server酱: SendKey is invalid or expired — check it at https://sct.ftqq.com')
    }
    const message = body && typeof body.message === 'string' ? body.message : raw.slice(0, 200)
    throw new Error(redact(`Server酱: send failed (HTTP ${res.status})${message ? ': ' + message : ''}`, key))
  }
  if (!body) throw new Error('Server酱: unexpected response, please retry')

  // Success is code 0. Number() so a stringified code is still caught; a 2xx with
  // no code at all (NaN) is treated as success.
  const code = Number(body.code)
  if (Number.isFinite(code) && code !== 0) {
    const message = String(body.message || 'send failed')
    if (code === 40001 || /invalid|无效|不存在|失效/i.test(message)) {
      throw new Error('Server酱: SendKey is invalid or expired — check it at https://sct.ftqq.com')
    }
    throw new Error(redact(`Server酱: ${message} (code ${code})`, key))
  }
  return body.data ?? { ok: true }
}

export function createServer(): McpServer {
  const server = new McpServer({ name: 'serverchan', version: '0.1.0' })

  server.registerTool(
    'serverchan_send',
    {
      description:
        'Push a notification to your own WeChat via Server酱 (also reaches 企业微信 / 钉钉群 / 飞书群 if configured there). Use for cron results, alerts and reminders.',
      inputSchema: z.object({
        title: z.string().min(1).describe('Notification title (required)'),
        desp: z.string().optional().describe('Markdown body'),
        short: z.string().optional().describe('Short summary shown in the push card'),
        tags: z.string().optional().describe('Pipe-delimited tags, e.g. "server|alert"'),
        channel: z.string().optional().describe('Channel number override, per Server酱 docs'),
      }),
    },
    async (input) => {
      try {
        const sendkey = requireEnv(
          'SERVERCHAN_SENDKEY',
          'Get one free at https://sct.ftqq.com (scan-login with WeChat, then copy the SendKey).',
        )
        const data = await send(sendkey, input)
        return { content: [{ type: 'text', text: `Sent. ${JSON.stringify(data)}` }] }
      } catch (e) {
        return { content: [{ type: 'text', text: e instanceof Error ? e.message : 'send failed' }], isError: true }
      }
    },
  )

  return server
}

/**
 * 中国法定节假日 / 调休 — is a given date a day off in mainland China?
 *
 * No credential, no signup. This is the one you can run in ten seconds.
 *
 * Source: NateScarlet/holiday-cn, a maintained JSON dataset of the State
 * Council's published 放假安排. Schema: { year, days: [{ name, date, isOffDay }] }.
 * Only SPECIAL days are listed — statutory holidays (isOffDay true) and 调休 makeup
 * workdays (isOffDay false, e.g. a Saturday you must work). Any date not listed is
 * ordinary: weekend = off, weekday = work.
 *
 * Why this dataset and not timor.tech (the API most tutorials use): timor.tech
 * sits behind a Cloudflare challenge that blocks non-CN server egress. Both GitHub
 * CDNs below answer from anywhere.
 */

import { McpServer } from '@modelcontextprotocol/server'
import * as z from 'zod/v4'
import { request } from '../lib/http.js'

export type HolidayDay = { name: string; date: string; isOffDay: boolean }
export type DayType = 'holiday' | 'makeup-workday' | 'weekend' | 'workday'

const CACHE_TTL_MS = 12 * 60 * 60 * 1000 // the dataset changes a few times a year
const YEAR_CACHE = new Map<number, { days: HolidayDay[]; map: Map<string, HolidayDay>; at: number }>()

const WEEKDAY_ZH = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']

export function isValidDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
  const [y, m, d] = value.split('-').map(Number)
  if (m < 1 || m > 12 || d < 1 || d > 31) return false
  const dt = new Date(Date.UTC(y, m - 1, d))
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d
}

function weekdayOf(date: string): { index: number; zh: string } {
  const [y, m, d] = date.split('-').map(Number)
  const index = new Date(Date.UTC(y, m - 1, d)).getUTCDay()
  return { index, zh: WEEKDAY_ZH[index] }
}

/** Today in China, whatever timezone the process runs in. en-CA formats as YYYY-MM-DD. */
export function todayInChina(): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai' }).format(new Date())
}

export function clearCache(): void {
  YEAR_CACHE.clear()
}

async function fetchYear(year: number): Promise<{ days: HolidayDay[]; map: Map<string, HolidayDay> }> {
  const cached = YEAR_CACHE.get(year)
  if (cached && Date.now() - cached.at < CACHE_TTL_MS) return { days: cached.days, map: cached.map }

  const urls = [
    `https://cdn.jsdelivr.net/gh/NateScarlet/holiday-cn@master/${year}.json`,
    `https://raw.githubusercontent.com/NateScarlet/holiday-cn/master/${year}.json`,
  ]
  let lastError = ''
  for (const url of urls) {
    try {
      const res = await request(url, {
        headers: { 'User-Agent': 'china-mcp-servers/0.1 (holiday)' },
        label: '节假日 holiday',
      })
      if (!res.ok) {
        lastError = `HTTP ${res.status}`
        continue
      }
      const body = (await res.json()) as { year?: unknown; days?: unknown }
      // Validate before trusting or caching. A CDN error page that happens to be
      // JSON — or a wrong-year file — must never be cached as an empty calendar:
      // that would silently report every statutory holiday as a normal workday
      // for the next 12 hours. A real year file always lists several days.
      if (Number(body.year) !== year || !Array.isArray(body.days) || body.days.length === 0) {
        lastError = 'schema mismatch'
        continue
      }
      const days: HolidayDay[] = body.days
        .map((d) => d as Record<string, unknown>)
        .filter((d) => typeof d.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(String(d.date)))
        .map((d) => ({ name: String(d.name || ''), date: String(d.date), isOffDay: d.isOffDay === true }))
      if (days.length === 0) {
        lastError = 'no valid days'
        continue
      }
      const map = new Map<string, HolidayDay>()
      for (const day of days) map.set(day.date, day)
      YEAR_CACHE.set(year, { days, map, at: Date.now() })
      return { days, map }
    } catch (e) {
      lastError = e instanceof Error ? e.message : 'fetch failed'
    }
  }
  throw new Error(`节假日 holiday: could not load the ${year} calendar (${lastError || 'source unavailable'})`)
}

export async function dayInfo(date?: string): Promise<{
  date: string
  weekday: string
  isOffDay: boolean
  type: DayType
  name: string | null
}> {
  const value = String(date || '').trim() || todayInChina()
  if (!isValidDate(value)) throw new Error('节假日 holiday: date must be YYYY-MM-DD')
  const { map } = await fetchYear(Number(value.slice(0, 4)))
  const { index, zh } = weekdayOf(value)
  const hit = map.get(value)
  if (hit) {
    return {
      date: value,
      weekday: zh,
      isOffDay: hit.isOffDay,
      type: hit.isOffDay ? 'holiday' : 'makeup-workday',
      name: hit.name || null,
    }
  }
  const isWeekend = index === 0 || index === 6
  return { date: value, weekday: zh, isOffDay: isWeekend, type: isWeekend ? 'weekend' : 'workday', name: null }
}

export async function yearInfo(year?: number): Promise<{
  year: number
  holidays: Array<{ name: string; date: string }>
  makeupWorkdays: Array<{ name: string; date: string }>
}> {
  let value: number
  if (year === undefined || String(year).trim() === '') {
    value = Number(todayInChina().slice(0, 4))
  } else {
    value = Number(year)
    if (!Number.isInteger(value) || value < 2007 || value > 2100) {
      throw new Error('节假日 holiday: year must be a valid year, e.g. 2026')
    }
  }
  const { days } = await fetchYear(value)
  return {
    year: value,
    holidays: days.filter((d) => d.isOffDay).map((d) => ({ name: d.name, date: d.date })),
    makeupWorkdays: days.filter((d) => !d.isOffDay).map((d) => ({ name: d.name, date: d.date })),
  }
}

export function createServer(): McpServer {
  const server = new McpServer({ name: 'china-holiday', version: '0.1.0' })

  server.registerTool(
    'holiday_check_date',
    {
      description:
        'Check whether a date is a day off in mainland China: statutory holiday, 调休 makeup workday, weekend, or ordinary workday. Defaults to today in China time. No credential needed.',
      inputSchema: z.object({
        date: z.string().optional().describe('YYYY-MM-DD; defaults to today in China time'),
      }),
    },
    async ({ date }) => {
      try {
        const info = await dayInfo(date)
        return { content: [{ type: 'text', text: JSON.stringify(info) }] }
      } catch (e) {
        return { content: [{ type: 'text', text: e instanceof Error ? e.message : 'lookup failed' }], isError: true }
      }
    },
  )

  server.registerTool(
    'holiday_list_year',
    {
      description:
        'List a year of mainland-China statutory holidays and the 调休 makeup workdays that pay for them. Defaults to the current year in China time.',
      inputSchema: z.object({
        year: z.number().int().optional().describe('e.g. 2026; defaults to the current China-time year'),
      }),
    },
    async ({ year }) => {
      try {
        const info = await yearInfo(year)
        return { content: [{ type: 'text', text: JSON.stringify(info) }] }
      } catch (e) {
        return { content: [{ type: 'text', text: e instanceof Error ? e.message : 'lookup failed' }], isError: true }
      }
    },
  )

  return server
}
